export type FaKey = keyof typeof fa;

const label = (key: string, fallback: string): string =>
  Object.prototype.hasOwnProperty.call(fa, key) ? fa[key as FaKey] : fallback;

/** Persian name of an SMS template key (core SMS_TEMPLATES); the key itself if one is ever missing. */
export const smsTemplateLabel = (template: string): string => label(`smsTemplate.${template}`, "قالب پیامک");

/** Persian name of a category status (core CATEGORY_STATUSES). */
export const categoryStatusLabel = (status: string): string => label(`catStatus.${status}`, "وضعیت نامشخص");

/** Persian name of a page template (core PAGE_TEMPLATES); the key itself if one is ever missing. */
export const pageTemplateLabel = (template: string): string => label(`pageTemplate.${template}`, "قالب عمومی");
export const collectionKindLabel = (kind: string): string => label(`collections.kind.${kind}`, "مجموعه");
